/**
 * The line classifier behind `generated-code-stats.mjs`.
 *
 * Each case is a shape a trimmed-line pattern gets wrong: `//` inside a string, code after the end of
 * a block comment, a multi-line verbatim or raw string whose lines look like comments. The header cases
 * pin what is left out of a generated file's counts — exactly the banner `CSharpTemplate.RenderHeader`
 * writes, and nothing a reader would call the file's content.
 *
 *   node --test scripts/csharp-lines.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { classifyLines, headerLength, measureSource } from './lib/csharp-lines.mjs';

const kinds = source => classifyLines(source).kinds;

// What CSharpTemplate.RenderHeader writes, verbatim, for a template that names all three lines.
const PRAGMATIC_HEADER = [
  '// <auto-generated/>',
  '// Generated by Pragmatic.Design, a framework by Alessandro Saiani',
  '// https://pragmaticdesign.net',
  '// This file belongs to your project; no rights are claimed in it.',
  '// Pragmatic.SourceGenerator/Result v1.0.0',
  '// Source: ClashError from TestApp.Errors',
  '// Trigger: Error registration for ClashError',
  '#nullable enable',
  '',
].join('\r\n');

test('a Pragmatic header is left out of every count, and reported on its own', () => {
  const body = 'using System;\r\n\r\nnamespace A;\r\n\r\ninternal static class B { }\r\n';
  const m = measureSource(`${PRAGMATIC_HEADER}\r\n${body}`, { header: true });

  assert.equal(m.headerLines, 9);
  assert.equal(m.headerChars, PRAGMATIC_HEADER.split('\r\n').join('').length);
  assert.deepEqual(
    { lines: m.lines, code: m.code, blank: m.blank, comment: m.comment, directive: m.directive },
    { lines: 5, code: 3, blank: 2, comment: 0, directive: 0 });
  assert.equal(m.chars, 'using System;namespace A;internal static class B { }'.length);
});

test('the control: without asking for it, the header is counted like any other line', () => {
  const m = measureSource(`${PRAGMATIC_HEADER}\r\nnamespace A;\r\n`);

  assert.equal(m.headerLines, 0);
  assert.equal(m.lines, 10);
  assert.equal(m.comment, 7);
  assert.equal(m.directive, 1);
});

test('the header stops at XML documentation: it belongs to the declaration below', () => {
  const source = '// <auto-generated/>\n#nullable enable\n\n/// <summary>Doc.</summary>\npublic class A { }\n';
  const classified = classifyLines(source);

  assert.equal(headerLength(classified), 3);
  assert.equal(measureSource(source, { header: true }).comment, 1);
});

test('the header is only at the top: a comment after code is a comment', () => {
  const source = 'namespace A;\n// not a banner\n';

  assert.equal(headerLength(classifyLines(source)), 0);
  assert.deepEqual(kinds(source), ['code', 'comment']);
});

test('// inside a string is code, and a trailing comment does not make a line a comment', () => {
  assert.deepEqual(kinds([
    'var url = "https://pragmaticdesign.net";',
    'var x = 1; // trailing',
    'var c = \'/\'; var d = \'"\';',
    'var e = "escaped \\" // still inside";',
  ].join('\n')), ['code', 'code', 'code', 'code']);
});

test('a block comment spans lines, and code after it on the same line is code', () => {
  assert.deepEqual(kinds([
    '/* opens',
    '   var x = 1; still inside',
    '',
    '   closes */ var y = 2;',
    'var z = 3; /* a comment',
    '   continues */',
  ].join('\n')), ['comment', 'comment', 'comment', 'code', 'code', 'comment']);
});

test('the lines of a verbatim string are code, whatever they hold', () => {
  assert.deepEqual(kinds([
    'var sql = @"SELECT *',
    '// looks like a comment',
    '',
    '  FROM ""t""";',
    '// a real comment',
  ].join('\n')), ['code', 'code', 'code', 'code', 'comment']);
});

test('the lines of a raw string are code, and /* inside one opens nothing', () => {
  assert.deepEqual(kinds([
    'var json = $$"""',
    '    /* not a comment',
    '',
    '    {"a": {{value}} }',
    '    """;',
    'var y = 1;',
    'var one = """single "line" raw""";',
  ].join('\n')), ['code', 'code', 'code', 'code', 'code', 'code', 'code']);
});

test('preprocessor lines are directives, blank lines are blank', () => {
  assert.deepEqual(kinds([
    '#pragma warning disable CS0618',
    '    #region Members',
    '',
    '   \t',
    'public int X;',
  ].join('\n')), ['directive', 'directive', 'blank', 'blank', 'code']);
});

test('CRLF and LF count the same, and characters leave the line breaks out', () => {
  const lf = measureSource('namespace A;\n\nclass B { }\n');
  const crlf = measureSource('namespace A;\r\n\r\nclass B { }\r\n');

  assert.deepEqual(crlf, lf);
  assert.equal(lf.chars, 'namespace A;class B { }'.length);
});

test('a byte-order mark is not a character of the file', () => {
  assert.deepEqual(measureSource('﻿namespace A;\n'), measureSource('namespace A;\n'));
});
